// The web decoder of the core's watched-videos bitfield, checked against
// strings the core's own encoder produced (tests/fixtures/watchedBitfield.json,
// generated by crates/watched-bitfield/tests/js_fixtures.rs, which also checks
// that the core decodes every case to the same answer).

const fixture = require('./fixtures/watchedBitfield.json');
const { decodeWatched, orderVideoIds } = require('../src/common/watchedBitfield');

describe('decodeWatched', () => {
    fixture.cases.forEach((testCase) => {
        test(`matches the core: ${testCase.name}`, () => {
            const decoded = decodeWatched(testCase.serialized, testCase.videoIds);
            if (testCase.anchorMissing) {
                // The core answers "nothing watched" when it cannot place the
                // bits; that is not knowledge, so the web says unknown.
                expect(decoded).toBeNull();
            } else {
                expect(decoded).toEqual(testCase.expected);
            }
        });
    });

    test('no watched field means nothing was marked watched', () => {
        expect(decodeWatched(null, ['a', 'b'])).toEqual([false, false]);
    });

    test('a malformed field is unknown, not "nothing watched"', () => {
        expect(decodeWatched('garbage', ['a'])).toBeNull();
        expect(decodeWatched('tt1:1:1:x:!!!!', ['tt1:1:1'])).toBeNull();
    });

    test('an empty video list is unknown', () => {
        expect(decodeWatched(fixture.cases[0].serialized, [])).toBeNull();
    });
});

describe('orderVideoIds', () => {
    test('sorts like the core: season, then episode, then release date; no season first', () => {
        const videos = [
            { id: 's1e2', season: 1, episode: 2, released: '2022-02-25T00:00:00.000Z' },
            { id: 's0e1', season: 0, episode: 1 },
            { id: 's1e1', season: 1, episode: 1, released: '2022-02-18T00:00:00.000Z' },
            { id: 'trailer' },
            { id: 's2e1', season: 2, episode: 1 },
        ];
        expect(orderVideoIds(videos)).toEqual(['trailer', 's0e1', 's1e1', 's1e2', 's2e1']);
    });

    test('ties on season and episode fall back to the release date', () => {
        const videos = [
            { id: 'late', season: 1, episode: 1, released: '2023-01-01T00:00:00.000Z' },
            { id: 'early', season: 1, episode: 1, released: '2022-01-01T00:00:00.000Z' },
        ];
        expect(orderVideoIds(videos)).toEqual(['early', 'late']);
    });
});
